function updateDirect(bhit)
{
   if(bhit)
   {
      _parent.scale_X = _root.game["p" + pn]._xscale >= 0 ? -1 : 1;
   }
   else
   {
      _parent.scale_X = _parent._x <= _root.game["p" + pn]._x ? 1 : -1;
   }
   _parent._xscale = _parent.scale_X * 100;
}

